```python
def transform(grid):
    import collections
    h, w = len(grid), len(grid[0])
    total = collections.Counter(v for row in grid for v in row)
    bg = total.most_common(1)[0][0]
    seen = [[False]*w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and not seen[r][c]:
                col = grid[r][c]
                stack = [(r, c)]
                seen[r][c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == col:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
                rs = [p[0] for p in cells]; cs = [p[1] for p in cells]
                bbox = (min(rs), min(cs), max(rs), max(cs))
                area = (bbox[2]-bbox[0]+1)*(bbox[3]-bbox[1]+1)
                density = len(cells)/area
                comps.append((density, len(cells), col, bbox))
    comps.sort(key=lambda t: (-t[0], -t[1]))
    out = [row[:] for row in grid]
    filled = [[False]*w for _ in range(h)]
    for density, size, col, (r0, c0, r1, c1) in comps:
        if density >= 0.75 and size >= 4:
            for r in range(r0, r1+1):
                for c in range(c0, c1+1):
                    if out[r][c] != col:
                        out[r][c] = col
                        filled[r][c] = True
    for r in range(h):
        for c in range(w):
            if filled[r][c]:
                continue
            col = grid[r][c]
            nbrs = [grid[r+dr][c+dc] for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0 <= r+dr < h and 0 <= c+dc < w]
            if col not in nbrs:
                out[r][c] = bg
    return out
